ROC=31
Bank=0x3102
# vqwk_buffer_offset = 0
sample_size=16564

! module.type, module.num  chan.num, det.type, det.name
! 3C11, 12, 16
! 3H02, 3H07A, 3H07C

!ADC0
VQWK, 0, 0, bpmstripline, BPM3C11XP
VQWK, 0, 1, bpmstripline, BPM3C11XM
VQWK, 0, 2, bpmstripline, BPM3C11YP
VQWK, 0, 3, bpmstripline, BPM3C11YM
VQWK, 0, 4, bpmstripline, BPM3C12XP
VQWK, 0, 5, bpmstripline, BPM3C12XM
VQWK, 0, 6, bpmstripline, BPM3C12YP
VQWK, 0, 7, bpmstripline, BPM3C12YM

!ADC1
VQWK, 1, 0, bpmstripline, BPM3C16XP
VQWK, 1, 1, bpmstripline, BPM3C16XM
VQWK, 1, 2, bpmstripline, BPM3C16YP
VQWK, 1, 3, bpmstripline, BPM3C16YM
VQWK, 1, 4, bpmstripline, BPM3H02XP
VQWK, 1, 5, bpmstripline, BPM3H02XM
VQWK, 1, 6, bpmstripline, BPM3H02YP
VQWK, 1, 7, bpmstripline, BPM3H02YM

!ADC2
VQWK, 2, 0, bpmstripline, BPM3H07AXP
VQWK, 2, 1, bpmstripline, BPM3H07AXM
VQWK, 2, 2, bpmstripline, BPM3H07AYP
VQWK, 2, 3, bpmstripline, BPM3H07AYM
VQWK, 2, 4, bpmstripline, BPM3H07BXP
VQWK, 2, 5, bpmstripline, BPM3H07BXM
VQWK, 2, 6, bpmstripline, BPM3H07BYP
VQWK, 2, 7, bpmstripline, BPM3H07BYM

!BCM
VQWK, 3, 0, bpmstripline, BPM3H07CXP
VQWK, 3, 1, bpmstripline, BPM3H07CXM
VQWK, 3, 2, bpmstripline, BPM3H07CYP
VQWK, 3, 3, bpmstripline, BPM3H07CYM
VQWK, 3, 4, bcm, BCM3H04A
VQWK, 3, 5, bcm, BCM3H04B

begin=combinedbpm
name=bpm_target
BPM3H07A, bpmstripline, 1.0, 1.0, 1.0
BPM3H07B, bpmstripline, 1.0, 1.0, 1.0
BPM3H07C, bpmstripline, 1.0, 1.0, 1.0
end=combinedbpm

begin=combinedbcm
name=bcm_target
BCM3H04A, bcm, 1.0
BCM3H04B, bcm, 1.0
end=combinedbcm

begin=energycalculator
name=target_energy
!name          type            ratios     property
BPM3C11,       bpmstripline,   0.00012,	  beamposition
BPM3C12,       bpmstripline,   0.00024,	  beamposition
BPM3C16,       bpmstripline,   0.00004,	  beamposition
bpm_target,    combinedbpm,    -0.00017,  targetbeamposition
bpm_target,    combinedbpm,    0.0026,    targetbeamangle   ! 2.6 rad/1000 for mrad slope (z in meters)
end=energycalculator

[PUBLISH]
 q_targ,  combobcm, bcm_target, c
 x_targ,  combobpm, bpm_target, x
 y_targ,  combobpm, bpm_target, y
 xp_targ, combobpm, bpm_target, xp
 yp_targ, combobpm, bpm_target, yp
 e_targ,   comboenergy,  target_energy,  e

!END